-- AP Automation - PostgreSQL schema (generated from the Django models).
-- `python manage.py migrate` creates exactly these tables. Table name = <app>_<model>.

CREATE TABLE "accounts_user" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "password" varchar(128) NOT NULL,
  "last_login" timestamp with time zone NULL,
  "is_superuser" boolean NOT NULL,
  "username" varchar(150) NOT NULL UNIQUE,
  "first_name" varchar(150) NOT NULL,
  "last_name" varchar(150) NOT NULL,
  "email" varchar(254) NOT NULL,
  "is_staff" boolean NOT NULL,
  "is_active" boolean NOT NULL,
  "date_joined" timestamp with time zone NOT NULL,
  "role" varchar(20) NOT NULL
);

CREATE TABLE "authtoken_token" (
  "key" varchar(40) NOT NULL PRIMARY KEY,
  "user_id" bigint NOT NULL UNIQUE,
  "created" timestamp with time zone NOT NULL
);

CREATE TABLE "accounts_auditlog" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NULL,
  "action" varchar(60) NOT NULL,
  "entity_type" varchar(40) NOT NULL,
  "entity_id" varchar(40) NOT NULL,
  "details" jsonb NOT NULL,
  "created_at" timestamp with time zone NOT NULL
);

CREATE TABLE "accounts_notification" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "user_id" bigint NULL,
  "role" varchar(20) NOT NULL,
  "title" varchar(200) NOT NULL,
  "body" text NOT NULL,
  "link" varchar(200) NOT NULL,
  "is_read" boolean NOT NULL,
  "created_at" timestamp with time zone NOT NULL
);

CREATE TABLE "vendors_vendor" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "code" varchar(20) NOT NULL UNIQUE,
  "name" varchar(200) NOT NULL,
  "gstin" varchar(15) NOT NULL,
  "pan" varchar(10) NOT NULL,
  "email" varchar(254) NOT NULL,
  "phone" varchar(20) NOT NULL,
  "address" text NOT NULL,
  "state_code" varchar(2) NOT NULL,
  "payment_terms_days" integer NOT NULL CHECK ("payment_terms_days" >= 0),
  "status" varchar(20) NOT NULL,
  "onboarding_comment" text NOT NULL,
  "created_by_id" bigint NULL,
  "approved_by_id" bigint NULL,
  "created_at" timestamp with time zone NOT NULL
);

CREATE TABLE "vendors_vendorbank" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "vendor_id" bigint NOT NULL,
  "account_name" varchar(200) NOT NULL,
  "account_number" varchar(20) NOT NULL,
  "ifsc" varchar(11) NOT NULL,
  "bank_name" varchar(100) NOT NULL,
  "branch" varchar(100) NOT NULL,
  "is_primary" boolean NOT NULL,
  "is_verified" boolean NOT NULL
);

CREATE TABLE "purchasing_purchaseorder" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "po_number" varchar(40) NOT NULL UNIQUE,
  "vendor_id" bigint NOT NULL,
  "po_date" date NOT NULL,
  "match_type" varchar(4) NOT NULL,
  "status" varchar(10) NOT NULL,
  "currency" varchar(3) NOT NULL
);

CREATE TABLE "purchasing_poline" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "po_id" bigint NOT NULL,
  "line_no" integer NOT NULL CHECK ("line_no" >= 0),
  "item_code" varchar(40) NOT NULL,
  "description" varchar(255) NOT NULL,
  "uom" varchar(10) NOT NULL,
  "quantity" numeric(12, 3) NOT NULL,
  "unit_price" numeric(14, 2) NOT NULL,
  "gst_rate" numeric(5, 2) NOT NULL
);

CREATE TABLE "purchasing_goodsreceipt" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "grn_number" varchar(40) NOT NULL UNIQUE,
  "po_id" bigint NOT NULL,
  "received_date" date NOT NULL
);

CREATE TABLE "purchasing_grnline" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "grn_id" bigint NOT NULL,
  "po_line_id" bigint NOT NULL,
  "quantity_received" numeric(12, 3) NOT NULL
);

CREATE TABLE "invoices_invoice" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "file" varchar(100) NOT NULL,
  "original_filename" varchar(255) NOT NULL,
  "file_hash" varchar(64) NOT NULL,
  "source" varchar(10) NOT NULL,
  "page_count" integer NOT NULL CHECK ("page_count" >= 0),
  "vendor_id" bigint NULL,
  "vendor_name_raw" varchar(255) NOT NULL,
  "vendor_gstin" varchar(15) NOT NULL,
  "invoice_number" varchar(60) NOT NULL,
  "invoice_date" date NULL,
  "due_date" date NULL,
  "po_number" varchar(40) NOT NULL,
  "purchase_order_id" bigint NULL,
  "currency" varchar(3) NOT NULL,
  "subtotal" numeric(14, 2) NULL,
  "cgst" numeric(14, 2) NOT NULL,
  "sgst" numeric(14, 2) NOT NULL,
  "igst" numeric(14, 2) NOT NULL,
  "total_amount" numeric(14, 2) NULL,
  "status" varchar(20) NOT NULL,
  "match_type_used" varchar(10) NOT NULL,
  "ocr_text" text NOT NULL,
  "ocr_engine" varchar(40) NOT NULL,
  "ocr_confidence" double precision NULL,
  "extracted_snapshot" jsonb NOT NULL,
  "ocr_accuracy" double precision NULL,
  "uploaded_by_id" bigint NULL,
  "received_at" timestamp with time zone NOT NULL,
  "approved_at" timestamp with time zone NULL,
  "paid_at" timestamp with time zone NULL
);

CREATE TABLE "invoices_invoiceline" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "invoice_id" bigint NOT NULL,
  "line_no" integer NOT NULL CHECK ("line_no" >= 0),
  "item_code" varchar(40) NOT NULL,
  "description" varchar(255) NOT NULL,
  "quantity" numeric(12, 3) NOT NULL,
  "unit_price" numeric(14, 2) NOT NULL,
  "gst_rate" numeric(5, 2) NOT NULL,
  "amount" numeric(14, 2) NOT NULL,
  "po_line_id" bigint NULL
);

CREATE TABLE "invoices_validationissue" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "invoice_id" bigint NOT NULL,
  "category" varchar(12) NOT NULL,
  "severity" varchar(8) NOT NULL,
  "message" varchar(300) NOT NULL,
  "created_at" timestamp with time zone NOT NULL
);

CREATE TABLE "workflow_approvalrule" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "name" varchar(100) NOT NULL,
  "min_amount" numeric(14, 2) NOT NULL,
  "max_amount" numeric(14, 2) NULL,
  "is_active" boolean NOT NULL
);

CREATE TABLE "workflow_approvalstep" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "rule_id" bigint NOT NULL,
  "stage" integer NOT NULL CHECK ("stage" >= 0),
  "role" varchar(20) NOT NULL,
  "sla_hours" integer NOT NULL CHECK ("sla_hours" >= 0),
  "escalation_role" varchar(20) NOT NULL
);

CREATE TABLE "workflow_approvaltask" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "invoice_id" bigint NOT NULL,
  "step_id" bigint NULL,
  "stage" integer NOT NULL CHECK ("stage" >= 0),
  "role" varchar(20) NOT NULL,
  "status" varchar(12) NOT NULL,
  "due_at" timestamp with time zone NOT NULL,
  "reminder_sent_at" timestamp with time zone NULL,
  "escalated" boolean NOT NULL,
  "decided_by_id" bigint NULL,
  "decided_at" timestamp with time zone NULL,
  "comment" text NOT NULL,
  "created_at" timestamp with time zone NOT NULL
);

CREATE TABLE "payments_payment" (
  "id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "payment_ref" varchar(20) NOT NULL UNIQUE,
  "invoice_id" bigint NOT NULL,
  "vendor_id" bigint NOT NULL,
  "bank_id" bigint NULL,
  "amount" numeric(14, 2) NOT NULL,
  "mode" varchar(6) NOT NULL,
  "status" varchar(10) NOT NULL,
  "bank_reference" varchar(40) NOT NULL,
  "failure_reason" varchar(200) NOT NULL,
  "due_date" date NULL,
  "requested_at" timestamp with time zone NOT NULL,
  "initiated_at" timestamp with time zone NULL,
  "paid_at" timestamp with time zone NULL,
  "released_by_id" bigint NULL
);

